 "content": "def transform(grid):
    """Extend each isolated marker by the matching horizontal edge sequence."""
    out = [row[:] for row in grid]
    h, w = len(grid), len(grid[0])
    templates = []
    # The nonzero runs at the top and bottom edges are the sequence keys.
    for r in {0, h - 1}:
        c = 0
        while c < w:
            if grid[r][c] == 0:
                c += 1
                continue
            start = c
            while c < w and grid[r][c] != 0:
                c += 1
            templates.append(grid[r][start:c])
    # Every non-edge nonzero cell is a seed: copy its associated sequence,
    # aligned so the matching color occupies the seed's original position.
    for r in range(1, h - 1):
        for c, color in enumerate(grid[r]):
            if color == 0:
                continue
            for seq in templates:
                for i, value in enumerate(seq):
                    if value == color:
                        start = c - i
                        for j, v in enumerate(seq):
                            x = start + j
                            if 0 <= x < w:
                                out[r][x] = v
                        break
                else:
                    continue
                break
    return out
